package sts1state;
import com.google.gson.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** UI-only fixtures, never human demonstrations. No original saves are read or changed. */
public final class HistoryIndexCheck {
    static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
    static JsonObject run(int i,long now){
        JsonObject run=new JsonObject();run.addProperty("schema",Recorder.SCHEMA);JsonObject m=new JsonObject();m.addProperty("run_id","history-ui-fixture-"+i);m.addProperty("seed","1234567890123456789");m.addProperty("dataset_origin","test_fixture");run.add("metadata",m);JsonArray records=new JsonArray();run.add("records",records);
        JsonObject state=new JsonObject();state.addProperty("class",new String[]{"IRONCLAD","THE_SILENT","DEFECT","WATCHER"}[i%4]);state.addProperty("ascension",i%21);state.addProperty("floor",40+i%10);state.addProperty("hp",67);state.addProperty("max_hp",80);state.addProperty("gold",99);JsonArray deck=new JsonArray();JsonObject card=new JsonObject();card.addProperty("id","Bash");card.addProperty("upgrades",1);card.addProperty("misc",i);deck.add(card);state.add("deck",deck);JsonArray relics=new JsonArray();JsonObject relic=new JsonObject();relic.addProperty("id","Burning Blood");relic.addProperty("counter",-1);relics.add(relic);state.add("relics",relics);
        JsonObject d=Recorder.object("decision");d.addProperty("decision_id","d-"+i);d.addProperty("branch_id","a");d.addProperty("time_ms",now-(i%40)*86400000L);d.addProperty("source","COMBAT_REWARD");d.addProperty("action_source","unknown");d.addProperty("candidate_id",i%3==0?"card:0":i%3==1?"skip":"bowl");d.add("before",state);JsonArray candidates=new JsonArray();for(String type:new String[]{"card","skip","bowl"}){JsonObject c=Recorder.object(type);c.addProperty("candidate_id",type.equals("card")?"card:0":type);if(type.equals("card"))c.add("card",card);candidates.add(c);}d.add("candidates",candidates);records.add(d);
        if(i%5!=0){JsonObject result=Recorder.object("result");result.addProperty("decision_id","d-"+i);result.addProperty("status","confirmed");result.addProperty("branch_id",i%2==0?"b":"a");result.addProperty("time_ms",now-(i%40)*86400000L);result.add("after",state);records.add(result);}
        if(i%4!=0){JsonObject end=Recorder.object("ending");end.addProperty("outcome",i%4==1?"victory":i%4==2?"death":"unknown");end.addProperty("branch_id","a");end.addProperty("time_ms",now-(i%40)*86400000L);end.add("state",state);records.add(end);}return run;
    }
    public static void main(String[] args)throws Exception{
        if(args[0].equals("--summary")){HistoryIndex.Summary s=HistoryIndex.readSummary(Paths.get(args[1]));JsonObject o=new JsonObject();o.addProperty("run_id",s.id);o.addProperty("picks",s.picks);o.addProperty("skips",s.skips);o.addProperty("bowls",s.bowls);o.addProperty("pending",s.pending);o.addProperty("outcome",s.outcome);o.addProperty("branches",s.branches.size());System.out.println(o);return;}
        Path root=Paths.get(args[0]);Files.createDirectories(root);long now=System.currentTimeMillis();List<Path> files=new ArrayList<>();Map<Path,byte[]> before=new HashMap<>();
        for(int i=0;i<1200;i++){Path file=root.resolve("fixture-"+i).resolve("run.json");Files.createDirectories(file.getParent());byte[] bytes=run(i,now).toString().getBytes(StandardCharsets.UTF_8);Files.write(file,bytes);files.add(file);before.put(file,bytes);}
        Path duplicate=root.resolve("duplicate/run.json");Files.createDirectories(duplicate.getParent());Files.write(duplicate,before.get(files.get(1)));Path broken=root.resolve("corrupt/run.json");Files.createDirectories(broken.getParent());Files.write(broken,"<broken>".getBytes(StandardCharsets.UTF_8));
        long start=System.nanoTime();HistoryIndex.Index index=HistoryIndex.scan(root,null);long scan=(System.nanoTime()-start)/1000000;
        check(index.runs.size()==1200,"same run counted once");check(index.duplicates==1&&index.errors.size()==1,"duplicate and corrupt reports");
        check(HistoryIndex.filter(index.runs,"IRONCLAD",-1,"",0,"",false,now).size()==300,"class");check(HistoryIndex.filter(index.runs,"",20,"",0,"",false,now).size()>0,"ascension 20");check(HistoryIndex.filter(index.runs,"",-1,"victory",0,"",false,now).size()==300,"victory");check(HistoryIndex.filter(index.runs,"",-1,"incomplete",0,"",false,now).size()==600,"missing or unknown ending not death");check(HistoryIndex.filter(index.runs,"",-1,"",7,"",false,now).size()==240,"date inclusive boundary");check(HistoryIndex.filter(index.runs,"",-1,"",30,"",false,now).size()==930,"30 days");for(HistoryIndex.Summary s:index.runs)s.localizedSearch="痛击";check(HistoryIndex.filter(index.runs,"",-1,"",0,"痛击",false,now).size()==1200,"UTF8 localized search");check(HistoryIndex.filter(index.runs,"",-1,"",0,"1234567890123456789",false,now).size()==1200,"64-bit seed string");check(HistoryIndex.filter(index.runs,"",-1,"",0,"Burning Blood",false,now).size()==1200,"relic ID");check(HistoryIndex.filter(index.runs,"",-1,"",0,"",true,now).size()==480,"SL branches not separate runs");check(HistoryIndex.filter(index.runs,"",-1,"",0,"不存在",false,now).isEmpty(),"no matches");
        HistoryIndex.Summary live=HistoryIndex.summarize(run(0,now),true);check(live.outcome.equals("current"),"live incomplete is current");check(HistoryIndex.summarize(run(3,now),true).outcome.equals("incomplete"),"unknown ending live not in progress");check(live.picks==0&&live.pending==1,"pending not counted");
        JsonObject slAfterDeath=run(2,now);JsonObject load=Recorder.object("load");load.addProperty("branch_id","new-attempt");slAfterDeath.getAsJsonArray("records").add(load);check(HistoryIndex.summarize(slAfterDeath,true).outcome.equals("current"),"SL after old branch death is current");check(HistoryIndex.summarize(slAfterDeath,false).outcome.equals("incomplete"),"SL missing latest ending is incomplete");
        JsonObject conflict=run(1,now);JsonObject contradictory=Recorder.copy(conflict.getAsJsonArray("records").get(1).getAsJsonObject());contradictory.addProperty("status","interrupted");conflict.getAsJsonArray("records").add(contradictory);check(HistoryIndex.summarize(conflict,false).skips==0,"conflicting result not complete");
        start=System.nanoTime();for(int i=0;i<100;i++)HistoryIndex.filter(index.runs,"IRONCLAD",-1,"",30,"Bash",false,now);long filtering=(System.nanoTime()-start)/1000000;
        for(Path p:files)check(Arrays.equals(before.get(p),Files.readAllBytes(p)),"read only");
        System.out.println("HistoryIndexCheck PASS: 1200 UI-only fixture runs, scan_ms="+scan+", 100_filters_ms="+filtering+", read-only, mixed class/outcome/date/SL/pending/conflict/corruption");
    }
}
